import dedent from "dedent";
import { getContext } from "./context.js";
import { resourceTypeSchemaName, runtimeResourceTypes } from "./resources.js";

const header = dedent`
  // This file is auto-generated by windmill-ts, do not modify it manually
  import { z } from 'zod';
  import * as wmill from 'windmill-client';
`;

const lazyObject = dedent`
  ${
    /* NOTE: Windmill has JSX enabled, so <T> is illegal.
             The usual way to fix this is <T,>, but some formatters/editors
             remove it, hence why a random constraint is used instead. */ ""
  }
  const lazyObject = <T extends unknown>(fn: () => T) => {
    let instance: T | null = null;
    return new Proxy({}, {
      get(_target, prop) {
        if (instance == null) {
          instance = fn();
        }

        let value = (instance as any)[prop];
        if (value instanceof Function) {
          value = value.bind(instance);
        }

        return value;
      }
    }) as T;
  }
`;

// With a runtime core, the client imports the runtime from it and re-exports
// its public part
const runtimeImports = (from: string) => {
  const values = [
    "lazyObject",
    ...runtimeResourceTypes().map(resourceTypeSchemaName),
    "_getResourceAs",
    "runScriptAsync as _startScript",
    "runFlowAsync as _startFlow",
  ];
  const types =
    "Cast, Transformer, ApplyTransformer, GetResourceOptions, ResourceResolverContext, ResourceResolverResult, ResourceResolver";
  const specifier = JSON.stringify(from);

  return [
    `import { ${values.join(", ")} } from ${specifier};`,
    `import type { ${types}, GetResourceReturnType } from ${specifier};`,
    `export { resolvedResource, setResourceResolver, getResourceResolver, getResourcePathsForType, isResourcePathOfType } from ${specifier};`,
    `export type { ${types} };`,
  ].join("\n");
};

export const writePreamble = async () => {
  const { write, runtimeImport } = getContext()!;

  await write(header);
  await write(runtimeImport == null ? lazyObject : runtimeImports(runtimeImport));
};
